def _update_width_intent(self, width):
        # Physical width can rebound by centimetres while the expert holds fruit.
        # Require sustained near-full opening; keep physical width continuous.
        # Five 30Hz samples exceed the longest (four) observed in v1 hold data.
        self._width_open_steps = self._width_open_steps + 1 if width >= self.config.gripper_open_width else 0
        if self._width_open_steps >= self.config.gripper_open_steps:
            self._gripper = 1.
        elif width < self._gripper_width_command - self.config.gripper_close_deadband:
            self._gripper = -1.
